GOLDENS = [
    pytest.param(
        v1001.SetScorePacket(
            type=v1001.ScorePacketType.CHANGE,
            score_info=[
                v1001.ScorePacketInfo(
                    scoreboard_id=v1001.ScoreboardId(raw_id=1),
                    objective_name="obj",
                    score_value=5,
                    identity_type=v1001.IdentityDefinition.Type.PLAYER,
                    player_id=v1001.PlayerScoreboardId(actor_unique_id=9),
                ),
                v1001.ScorePacketInfo(
                    scoreboard_id=v1001.ScoreboardId(raw_id=2),
                    objective_name="obj",
                    score_value=6,
                    identity_type=v1001.IdentityDefinition.Type.ENTITY,
                    entity_id=11,
                ),
                v1001.ScorePacketInfo(
                    scoreboard_id=v1001.ScoreboardId(raw_id=3),
                    objective_name="obj",
                    score_value=7,
                    identity_type=v1001.IdentityDefinition.Type.FAKE_PLAYER,
                    fake_player_name="fake",
                ),
            ],
        ),
        V1001_CHANGE,
        id="v1001-change",
    ),
    pytest.param(
        v1001.SetScorePacket(
            type=v1001.ScorePacketType.REMOVE,
            removed_score_info=[
                v1001.SetScorePacket.RemovedScorePacketInfo(
                    scoreboard_id=v1001.ScoreboardId(raw_id=1), objective_name="rm", score_value=0
                )
            ],
        ),
        V1001_REMOVE,
        id="v1001-remove",
    ),
    pytest.param(
        v2168.SetScorePacket(
            score_info=[
                v2168.RemoveScore(scoreboard_id=v2168.ScoreboardId(raw_id=1), objective_name="rm"),
                v2168.ChangePlayerScore(
                    scoreboard_id=v2168.ScoreboardId(raw_id=2),
                    objective_name="obj",
                    score_value=5,
                    player_id=v2168.PlayerScoreboardId(actor_unique_id=9),
                ),
                v2168.ChangeEntityScore(
                    scoreboard_id=v2168.ScoreboardId(raw_id=3), objective_name="obj", score_value=6, entity_id=11
                ),
                v2168.ChangeFakePlayerScore(
                    scoreboard_id=v2168.ScoreboardId(raw_id=4),
                    objective_name="obj",
                    score_value=7,
                    fake_player_name="fake",
                ),
            ]
        ),
        V2168,
        id="v2168",
    ),
    pytest.param(
        v2168.SetScorePacket(
            score_info=[v2168.RemoveScore(scoreboard_id=v2168.ScoreboardId(raw_id=1), objective_name="rm")]
        ),
        V2168_REMOVE_WITH_OBJECTIVE,
        id="v2168-remove-with-objective-name",
    ),
    pytest.param(
        v2168.SetScorePacket(
            score_info=[v2168.RemoveScore(scoreboard_id=v2168.ScoreboardId(raw_id=1), objective_name=None)]
        ),
        V2168_REMOVE_WITHOUT_OBJECTIVE,
        id="v2168-remove-without-objective-name",
    ),
]


@pytest.mark.parametrize("version", [v975, v1001, v2168])
def test_set_score_is_packet_108(version):
    assert version.packets[108] is version.SetScorePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_score_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_score_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(
    ("version", "body"),
    [
        pytest.param(v2168, V1001_CHANGE, id="v1001-body-as-v2168"),
        pytest.param(v1001, V2168, id="v2168-body-as-v1001"),
    ],
)
def test_set_score_body_of_the_other_era_leaves_trailing_bytes(version, body):
    with pytest.raises(ValueError, match="trailing bytes"):
        version.SetScorePacket.from_bytes(body)
